const src = $json.body || $json || {};
const requestedRaw = Array.isArray(src.phones) && src.phones.length
  ? src.phones
  : (src.phone ? [src.phone] : ['0998299109', '21999910781']);

function digits(v) {
  return String(v || '').replace(/\D/g, '');
}

const groups = {
  KIA: ['0998299109', '593998299109', '998299109'],
  HYUNDAI: ['21999910781', '5521999910781', '521999910781'],
};

const selected = new Set();
const invalid = [];
for (const raw of requestedRaw) {
  const d = digits(raw);
  let matched = false;
  for (const [group, aliases] of Object.entries(groups)) {
    if (aliases.includes(d)) {
      selected.add(group);
      matched = true;
    }
  }
  if (!matched) invalid.push(String(raw));
}

if (invalid.length) {
  throw new Error(`Only QA allowlist phones are accepted. Invalid: ${invalid.join(', ')}`);
}
if (!selected.size) {
  throw new Error('At least one QA phone is required');
}

const dryRun = src.dry_run !== false && String(src.dry_run ?? 'true').toLowerCase() !== 'false';
const confirm = String(src.confirm || '');
if (!dryRun && confirm !== 'DELETE_QA_CONVERSATIONS') {
  throw new Error('Real cleanup requires confirm="DELETE_QA_CONVERSATIONS"');
}

const cleanupQaRuns = src.cleanup_qa_runs === true || String(src.cleanup_qa_runs || '').toLowerCase() === 'true';
const aliases = [...selected].flatMap(group => groups[group]);

return [{
  json: {
    requested_phones: requestedRaw.map(String),
    selected_groups: [...selected],
    allowed_alias_digits: [...new Set(aliases)],
    dry_run: dryRun,
    confirm,
    cleanup_qa_runs: cleanupQaRuns,
    requested_by: src.requested_by || 'manual',
  }
}];

