SET search_path TO sales_prod, public, extensions;
DROP TABLE IF EXISTS _cris_safe_cleanup_params;
DROP TABLE IF EXISTS _phone_aliases;
DROP TABLE IF EXISTS _target_leads;
DROP TABLE IF EXISTS _target_convs;
DROP TABLE IF EXISTS _cleanup_counts;
DROP TABLE IF EXISTS _residual_counts;

CREATE TEMP TABLE _cris_safe_cleanup_params ON COMMIT DROP AS
SELECT
  $1::jsonb AS requested_phones,
  $2::jsonb AS allowed_alias_digits,
  $3::boolean AS dry_run,
  $4::text AS confirm_token,
  $5::boolean AS cleanup_qa_runs;

CREATE TEMP TABLE _phone_aliases ON COMMIT DROP AS
SELECT DISTINCT regexp_replace(value, '\D', '', 'g') AS digits
FROM _cris_safe_cleanup_params p,
     jsonb_array_elements_text(p.allowed_alias_digits) AS value
WHERE regexp_replace(value, '\D', '', 'g') <> '';

CREATE TEMP TABLE _target_leads (
  id uuid PRIMARY KEY,
  quicklink_id integer,
  telefono_1 text,
  marca text,
  conversacion_id uuid
) ON COMMIT DROP;

CREATE TEMP TABLE _target_convs (
  id uuid PRIMARY KEY,
  lead_id uuid,
  chatwoot_conv_id integer,
  chatwoot_contact_id integer
) ON COMMIT DROP;

CREATE TEMP TABLE _cleanup_counts (
  seq serial,
  table_name text,
  action text,
  affected integer
) ON COMMIT DROP;

CREATE TEMP TABLE _residual_counts (
  seq serial,
  table_name text,
  residual integer
) ON COMMIT DROP;

CREATE OR REPLACE FUNCTION pg_temp.cris_safe_table_exists(p_table text)
RETURNS boolean
LANGUAGE sql
STABLE
AS $fn$
  SELECT EXISTS (
    SELECT 1
    FROM information_schema.tables
    WHERE table_schema = 'public'
      AND table_name = p_table
  );
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.cris_safe_col_exists(p_table text, p_col text)
RETURNS boolean
LANGUAGE sql
STABLE
AS $fn$
  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = p_table
      AND column_name = p_col
  );
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.cris_safe_phone_match(p_value text)
RETURNS boolean
LANGUAGE sql
STABLE
AS $fn$
  WITH d AS (
    SELECT regexp_replace(coalesce(p_value, ''), '\D', '', 'g') AS digits
  )
  SELECT EXISTS (
    SELECT 1
    FROM d, _phone_aliases a
    WHERE d.digits <> ''
      AND length(d.digits) >= 9
      AND length(a.digits) >= 9
      AND (
        d.digits = a.digits
        OR d.digits LIKE '%' || a.digits
        OR a.digits LIKE '%' || d.digits
      )
  );
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.cris_safe_apply(
  p_table text,
  p_action text,
  p_condition text,
  p_dry_run boolean
)
RETURNS integer
LANGUAGE plpgsql
AS $fn$
DECLARE
  v_count integer := 0;
BEGIN
  IF coalesce(p_condition, '') = '' THEN
    v_count := 0;
  ELSIF p_dry_run THEN
    EXECUTE format('SELECT count(*)::integer FROM sales_prod.%I t WHERE %s', p_table, p_condition)
      INTO v_count;
  ELSE
    EXECUTE format('WITH deleted AS (DELETE FROM sales_prod.%I t WHERE %s RETURNING 1) SELECT count(*)::integer FROM deleted', p_table, p_condition)
      INTO v_count;
  END IF;

  INSERT INTO _cleanup_counts(table_name, action, affected)
  VALUES (p_table, CASE WHEN p_dry_run THEN 'would_' || p_action ELSE p_action END, coalesce(v_count, 0));
  RETURN coalesce(v_count, 0);
END;
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.cris_safe_residual(
  p_table text,
  p_condition text
)
RETURNS integer
LANGUAGE plpgsql
AS $fn$
DECLARE
  v_count integer := 0;
BEGIN
  IF coalesce(p_condition, '') = '' THEN
    v_count := 0;
  ELSE
    EXECUTE format('SELECT count(*)::integer FROM sales_prod.%I t WHERE %s', p_table, p_condition)
      INTO v_count;
  END IF;

  INSERT INTO _residual_counts(table_name, residual)
  VALUES (p_table, coalesce(v_count, 0));
  RETURN coalesce(v_count, 0);
END;
$fn$;

DO $do$
DECLARE
  v_dry_run boolean;
  v_confirm text;
  v_cleanup_qa_runs boolean;
  conds text[];
  cond text;
  sql text;
  set_list text[];
  selected text;
  affected integer;
BEGIN
  SELECT dry_run, confirm_token, cleanup_qa_runs
  INTO v_dry_run, v_confirm, v_cleanup_qa_runs
  FROM _cris_safe_cleanup_params;

  IF NOT v_dry_run AND v_confirm <> 'DELETE_QA_CONVERSATIONS' THEN
    RAISE EXCEPTION 'Real cleanup requires confirm=DELETE_QA_CONVERSATIONS';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM _phone_aliases) THEN
    RAISE EXCEPTION 'No allowlisted QA phone aliases were provided';
  END IF;

  IF pg_temp.cris_safe_table_exists('leads_quicklink') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'telefono_1') THEN
      conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.telefono_1::text)');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'telefono_2') THEN
      conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.telefono_2::text)');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'telefono') THEN
      conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.telefono::text)');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'wa_id') THEN
      conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.wa_id::text)');
    END IF;
    cond := array_to_string(conds, ' OR ');
    IF coalesce(cond, '') <> '' THEN
      sql := format(
        'INSERT INTO _target_leads(id, quicklink_id, telefono_1, marca, conversacion_id) ' ||
        'SELECT t.id, %s, %s, %s, %s FROM sales_prod.leads_quicklink t WHERE %s ON CONFLICT (id) DO NOTHING',
        CASE WHEN pg_temp.cris_safe_col_exists('leads_quicklink', 'quicklink_id') THEN 't.quicklink_id::integer' ELSE 'NULL::integer' END,
        CASE WHEN pg_temp.cris_safe_col_exists('leads_quicklink', 'telefono_1') THEN 't.telefono_1::text' ELSE 'NULL::text' END,
        CASE WHEN pg_temp.cris_safe_col_exists('leads_quicklink', 'marca') THEN 't.marca::text' ELSE 'NULL::text' END,
        CASE WHEN pg_temp.cris_safe_col_exists('leads_quicklink', 'conversacion_id') THEN 't.conversacion_id::uuid' ELSE 'NULL::uuid' END,
        cond
      );
      EXECUTE sql;
    END IF;
  END IF;

  INSERT INTO _cleanup_counts(table_name, action, affected)
  SELECT 'leads_quicklink', 'target', count(*)::integer FROM _target_leads;

  IF pg_temp.cris_safe_table_exists('conversaciones') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('conversaciones', 'lead_id') THEN
      conds := array_append(conds, 't.lead_id IN (SELECT id FROM _target_leads)');
    END IF;
    conds := array_append(conds, 't.id IN (SELECT conversacion_id FROM _target_leads WHERE conversacion_id IS NOT NULL)');
    IF pg_temp.cris_safe_col_exists('conversaciones', 'telefono') THEN
      conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.telefono::text)');
    END IF;
    IF pg_temp.cris_safe_col_exists('conversaciones', 'wa_id') THEN
      conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.wa_id::text)');
    END IF;
    cond := array_to_string(conds, ' OR ');
    sql := format(
      'INSERT INTO _target_convs(id, lead_id, chatwoot_conv_id, chatwoot_contact_id) ' ||
      'SELECT t.id, %s, %s, %s FROM sales_prod.conversaciones t WHERE %s ON CONFLICT (id) DO NOTHING',
      CASE WHEN pg_temp.cris_safe_col_exists('conversaciones', 'lead_id') THEN 't.lead_id::uuid' ELSE 'NULL::uuid' END,
      CASE WHEN pg_temp.cris_safe_col_exists('conversaciones', 'chatwoot_conv_id') THEN 't.chatwoot_conv_id::integer' ELSE 'NULL::integer' END,
      CASE WHEN pg_temp.cris_safe_col_exists('conversaciones', 'chatwoot_contact_id') THEN 't.chatwoot_contact_id::integer' ELSE 'NULL::integer' END,
      cond
    );
    EXECUTE sql;
  END IF;

  IF pg_temp.cris_safe_table_exists('lead_memory') AND pg_temp.cris_safe_col_exists('lead_memory', 'conversation_id') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('lead_memory', 'lead_id') THEN
      conds := array_append(conds, 'lm.lead_id IN (SELECT id FROM _target_leads)');
    END IF;
    IF pg_temp.cris_safe_col_exists('lead_memory', 'phone') THEN
      conds := array_append(conds, 'pg_temp.cris_safe_phone_match(lm.phone::text)');
    END IF;
    cond := array_to_string(conds, ' OR ');
    IF coalesce(cond, '') <> '' THEN
      sql := format('INSERT INTO _target_convs(id) SELECT DISTINCT lm.conversation_id FROM sales_prod.lead_memory lm WHERE lm.conversation_id IS NOT NULL AND (%s) ON CONFLICT (id) DO NOTHING', cond);
      EXECUTE sql;
    END IF;
  END IF;

  IF pg_temp.cris_safe_table_exists('conversaciones') THEN
    sql := format(
      'UPDATE _target_convs tc SET lead_id = COALESCE(%s, tc.lead_id), chatwoot_conv_id = COALESCE(%s, tc.chatwoot_conv_id), chatwoot_contact_id = COALESCE(%s, tc.chatwoot_contact_id) FROM sales_prod.conversaciones t WHERE t.id = tc.id',
      CASE WHEN pg_temp.cris_safe_col_exists('conversaciones', 'lead_id') THEN 't.lead_id::uuid' ELSE 'NULL::uuid' END,
      CASE WHEN pg_temp.cris_safe_col_exists('conversaciones', 'chatwoot_conv_id') THEN 't.chatwoot_conv_id::integer' ELSE 'NULL::integer' END,
      CASE WHEN pg_temp.cris_safe_col_exists('conversaciones', 'chatwoot_contact_id') THEN 't.chatwoot_contact_id::integer' ELSE 'NULL::integer' END
    );
    EXECUTE sql;
  END IF;

  INSERT INTO _cleanup_counts(table_name, action, affected)
  SELECT 'conversaciones', 'target', count(*)::integer FROM _target_convs;

  IF pg_temp.cris_safe_table_exists('leads_quicklink') THEN
    set_list := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'estado_agente') THEN
      set_list := array_append(set_list, 'estado_agente = ''PENDIENTE''');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'conversacion_id') THEN
      set_list := array_append(set_list, 'conversacion_id = NULL');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'reportado_ql') THEN
      set_list := array_append(set_list, 'reportado_ql = false');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'reportado_ql_at') THEN
      set_list := array_append(set_list, 'reportado_ql_at = NULL');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'fecha_final_gestion') THEN
      set_list := array_append(set_list, 'fecha_final_gestion = NULL');
    END IF;
    IF pg_temp.cris_safe_col_exists('leads_quicklink', 'updated_at') THEN
      set_list := array_append(set_list, 'updated_at = now()');
    END IF;
    IF array_length(set_list, 1) IS NOT NULL THEN
      cond := 't.id IN (SELECT id FROM _target_leads)';
      IF v_dry_run THEN
        EXECUTE 'SELECT count(*)::integer FROM sales_prod.leads_quicklink t WHERE ' || cond INTO affected;
      ELSE
        EXECUTE 'WITH updated AS (UPDATE sales_prod.leads_quicklink t SET ' || array_to_string(set_list, ', ') || ' WHERE ' || cond || ' RETURNING 1) SELECT count(*)::integer FROM updated' INTO affected;
      END IF;
      INSERT INTO _cleanup_counts(table_name, action, affected)
      VALUES ('leads_quicklink', CASE WHEN v_dry_run THEN 'would_reset_pending' ELSE 'reset_pending' END, coalesce(affected, 0));
    END IF;
  END IF;

  IF pg_temp.cris_safe_table_exists('scheduled_followups') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('scheduled_followups', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    IF pg_temp.cris_safe_col_exists('scheduled_followups', 'phone') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.phone::text)'); END IF;
    PERFORM pg_temp.cris_safe_apply('scheduled_followups', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('eventos_conversacion') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('eventos_conversacion', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    IF pg_temp.cris_safe_col_exists('eventos_conversacion', 'conversacion_id') THEN conds := array_append(conds, 't.conversacion_id IN (SELECT id FROM _target_convs)'); END IF;
    PERFORM pg_temp.cris_safe_apply('eventos_conversacion', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('transferencias_humano') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('transferencias_humano', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    IF pg_temp.cris_safe_col_exists('transferencias_humano', 'conversacion_id') THEN conds := array_append(conds, 't.conversacion_id IN (SELECT id FROM _target_convs)'); END IF;
    IF pg_temp.cris_safe_col_exists('transferencias_humano', 'lead_id') THEN conds := array_append(conds, 't.lead_id IN (SELECT id FROM _target_leads)'); END IF;
    IF pg_temp.cris_safe_col_exists('transferencias_humano', 'telefono') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.telefono::text)'); END IF;
    IF pg_temp.cris_safe_col_exists('transferencias_humano', 'chatwoot_conv_id') THEN conds := array_append(conds, 't.chatwoot_conv_id IN (SELECT chatwoot_conv_id FROM _target_convs WHERE chatwoot_conv_id IS NOT NULL)'); END IF;
    PERFORM pg_temp.cris_safe_apply('transferencias_humano', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('datos_calificacion') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('datos_calificacion', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    PERFORM pg_temp.cris_safe_apply('datos_calificacion', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('conversation_memory') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('conversation_memory', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    PERFORM pg_temp.cris_safe_apply('conversation_memory', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('agent_decisions') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('agent_decisions', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    PERFORM pg_temp.cris_safe_apply('agent_decisions', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('sync_queue') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('sync_queue', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    PERFORM pg_temp.cris_safe_apply('sync_queue', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('intentos_contacto') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('intentos_contacto', 'conversacion_id') THEN conds := array_append(conds, 't.conversacion_id IN (SELECT id FROM _target_convs)'); END IF;
    PERFORM pg_temp.cris_safe_apply('intentos_contacto', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('whatsapp_interaction_events') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('whatsapp_interaction_events', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    IF pg_temp.cris_safe_col_exists('whatsapp_interaction_events', 'phone') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.phone::text)'); END IF;
    PERFORM pg_temp.cris_safe_apply('whatsapp_interaction_events', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('conversation_context') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('conversation_context', 'chatwoot_conv_id') THEN conds := array_append(conds, 't.chatwoot_conv_id IN (SELECT chatwoot_conv_id FROM _target_convs WHERE chatwoot_conv_id IS NOT NULL)'); END IF;
    IF pg_temp.cris_safe_col_exists('conversation_context', 'contact_phone') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.contact_phone::text)'); END IF;
    PERFORM pg_temp.cris_safe_apply('conversation_context', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('lead_campaign_queue') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('lead_campaign_queue', 'lead_id') THEN conds := array_append(conds, 't.lead_id IN (SELECT id FROM _target_leads)'); END IF;
    IF pg_temp.cris_safe_col_exists('lead_campaign_queue', 'phone') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.phone::text)'); END IF;
    PERFORM pg_temp.cris_safe_apply('lead_campaign_queue', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('lead_memory') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('lead_memory', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _target_convs)'); END IF;
    IF pg_temp.cris_safe_col_exists('lead_memory', 'lead_id') THEN conds := array_append(conds, 't.lead_id IN (SELECT id FROM _target_leads)'); END IF;
    IF pg_temp.cris_safe_col_exists('lead_memory', 'phone') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.phone::text)'); END IF;
    IF pg_temp.cris_safe_col_exists('lead_memory', 'chatwoot_conv_id') THEN conds := array_append(conds, 't.chatwoot_conv_id IN (SELECT chatwoot_conv_id FROM _target_convs WHERE chatwoot_conv_id IS NOT NULL)'); END IF;
    PERFORM pg_temp.cris_safe_apply('lead_memory', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF v_cleanup_qa_runs AND pg_temp.cris_safe_table_exists('cris_test_cases') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.cris_safe_col_exists('cris_test_cases', 'phone') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.phone::text)'); END IF;
    IF pg_temp.cris_safe_col_exists('cris_test_cases', 'phone_e164') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.phone_e164::text)'); END IF;
    PERFORM pg_temp.cris_safe_apply('cris_test_cases', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('conversaciones') THEN
    conds := ARRAY[]::text[];
    conds := array_append(conds, 't.id IN (SELECT id FROM _target_convs)');
    IF pg_temp.cris_safe_col_exists('conversaciones', 'lead_id') THEN conds := array_append(conds, 't.lead_id IN (SELECT id FROM _target_leads)'); END IF;
    IF pg_temp.cris_safe_col_exists('conversaciones', 'telefono') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.telefono::text)'); END IF;
    PERFORM pg_temp.cris_safe_apply('conversaciones', 'delete', array_to_string(conds, ' OR '), v_dry_run);
  END IF;

  IF pg_temp.cris_safe_table_exists('conversaciones') THEN
    conds := ARRAY['t.id IN (SELECT id FROM _target_convs)'];
    IF pg_temp.cris_safe_col_exists('conversaciones', 'lead_id') THEN conds := array_append(conds, 't.lead_id IN (SELECT id FROM _target_leads)'); END IF;
    IF pg_temp.cris_safe_col_exists('conversaciones', 'telefono') THEN conds := array_append(conds, 'pg_temp.cris_safe_phone_match(t.telefono::text)'); END IF;
    PERFORM pg_temp.cris_safe_residual('conversaciones', array_to_string(conds, ' OR '));
  END IF;
  IF pg_temp.cris_safe_table_exists('lead_memory') THEN
    conds := ARRAY[]::text[];
